        'def sanitize_segment(raw: Any, fallback: str) -> str:\n'
        '    """Sanitize a filename or directory component against path traversal."""\n'
        '    cleaned = re.sub(r"[^A-Za-z0-9._-]+", "_", str(raw or "").strip()).strip("._")\n'
        '    return fallback if (not cleaned or cleaned in (".", "..")) else cleaned\n'
