        'def is_newer_version(latest: str, current: str) -> bool:\n'
        '    """Return True if latest is strictly greater than current."""\n'
        '    norm_latest = str(latest or "0").strip().lstrip("vV")\n'
        '    norm_current = str(current or "0").strip().lstrip("vV")\n'
        '    if norm_latest == norm_current:\n'
        '        return False\n'
        '\n'
        '    try:\n'
        '        from packaging.version import InvalidVersion, parse as parse_version\n'
        '\n'
        '        return parse_version(norm_latest) > parse_version(norm_current)\n'
        '    except (ImportError, InvalidVersion):\n'
        '        def _key(ver: str) -> list[tuple[int, Any]]:\n'
        '            return [\n'
        '                (0, int(tok)) if tok.isdigit() else (1, tok.lower())\n'
        '                for tok in re.split(r"[._-]+", ver)\n'
        '            ]\n'
        '\n'
        '        return _key(norm_latest) > _key(norm_current)\n'
        '\n'
        '\n'
        'def get_plugins(force_refresh: bool = False) -> list[dict[str, Any]]:\n'
        '    """Fetch plugin metadata with TTL cache, never holding CACHE_LOCK during HTTP I/O."""\n'
        '    now = time.time()\n'
        '    with CACHE_LOCK:\n'
        '        items = PLUGINS_CACHE["items"]\n'
        '        if not force_refresh:\n'
        '            if items and (now - float(PLUGINS_CACHE["fetched_at"]) < CACHE_TTL_SECONDS):\n'
        '                return [dict(item) for item in items]\n'
        '            if now - float(PLUGINS_CACHE["last_attempt_at"]) < CACHE_RETRY_COOLDOWN_SECONDS:\n'
        '                return [dict(item) for item in items]\n'
        '        PLUGINS_CACHE["last_attempt_at"] = now\n'
        '\n'
        '    fetched: Optional[list[dict[str, Any]]] = None\n'
        '    try:\n'
        '        resp = requests.get(f"{API_BASE}/plugins", timeout=5, proxies=NO_PROXY)\n'
