        '    except requests.RequestException as exc:\n'
        '        logger.error("Failed to fetch plugins: %s", exc)\n'
        '\n'
        '    with CACHE_LOCK:\n'
        '        if fetched is not None:\n'
        '            PLUGINS_CACHE["items"] = fetched\n'
        '            PLUGINS_CACHE["fetched_at"] = time.time()\n'
