        '\n'
        '\n'
        'def extract_py_plugin_metadata(file_path: str) -> dict[str, Any]:\n'
        '    """Safely inspect top-level plugin constants (UUID, CREDITS, VERSION, NAME) via AST."""\n'
        '    info: dict[str, Any] = {\n'
        '        "uuid": None,\n'
        '        "credits": None,\n'
        '        "version": None,\n'
        '        "name": None,\n'
        '        "is_hub_loader": False,\n'
        '    }\n'
        '    try:\n'
        '        with open(file_path, "r", encoding="utf-8", errors="ignore") as f:\n'
        '            source = f.read()\n'
        '    except OSError as exc:\n'
        '        logger.debug("Skipping unreadable plugin file %s: %s", file_path, exc)\n'
        '        return info\n'
        '\n'
        '    first_line = source.splitlines()[0] if source else ""\n'
        '    info["is_hub_loader"] = LOADER_HEADER in first_line\n'
        '\n'
        '    try:\n'
        '        tree = ast.parse(source, filename=file_path)\n'
        '    except SyntaxError:\n'
        '        return info\n'
        '\n'
        '    for node in tree.body:\n'
        '        target_name: Optional[str] = None\n'
        '        val_node: Optional[ast.AST] = None\n'
        '        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):\n'
        '            target_name = node.targets[0].id\n'
        '            val_node = node.value\n'
        '        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):\n'
        '            target_name = node.target.id\n'
        '            val_node = node.value\n'
        '\n'
        '        if target_name in ("UUID", "CREDITS", "VERSION", "NAME") and val_node is not None:\n'
        '            if isinstance(val_node, ast.Constant) and isinstance(val_node.value, str):\n'
        '                info[target_name.lower()] = val_node.value.strip()\n'
        '    return info\n'
        '\n'
        '\n'
        'def _matches_creator(file_credits: Optional[str], expected_credits: Optional[str]) -> bool:\n'
        '    if not file_credits or not expected_credits:\n'
        '        return False\n'
        '    return expected_credits.strip().lower() in file_credits.strip().lower()\n'
        '\n'
        '\n'
        'def _iter_matching_legacy_files(\n'
        '    target_uuid: Optional[str],\n'
        '    expected_credits: Optional[str] = "@w1bbex",\n'
        '    exclude_paths: Optional[list[str]] = None,\n'
        ') -> list[tuple[os.DirEntry[str], dict[str, Any]]]:\n'
        '    """Return non-loader .py entries in plugins_dir matching target_uuid and expected_credits."""\n'
        '    norm_uuid = str(target_uuid or "").strip().lower()\n'
        '    if not norm_uuid:\n'
        '        return []\n'
        '    plugins_dir = PATHS.plugins_dir\n'
        '    if not os.path.isdir(plugins_dir):\n'
        '        return []\n'
        '\n'
        '    excluded = {os.path.normcase(os.path.abspath(PATHS.hub_file))}\n'
        '    for path in exclude_paths or ():\n'
        '        if path:\n'
        '            excluded.add(os.path.normcase(os.path.abspath(path)))\n'
        '\n'
        '    with os.scandir(plugins_dir) as it:\n'
        '        entries = sorted(\n'
        '            (e for e in it if e.is_file() and e.name.lower().endswith(".py")),\n'
        '            key=lambda e: e.name,\n'
        '        )\n'
        '\n'
        '    matches: list[tuple[os.DirEntry[str], dict[str, Any]]] = []\n'
        '    for entry in entries:\n'
        '        if os.path.normcase(os.path.abspath(entry.path)) in excluded:\n'
        '            continue\n'
        '        meta = extract_py_plugin_metadata(entry.path)\n'
        '        if meta.get("is_hub_loader"):\n'
        '            continue\n'
        '        if str(meta.get("uuid") or "").strip().lower() != norm_uuid:\n'
        '            continue\n'
        '        if expected_credits and not _matches_creator(meta.get("credits"), expected_credits):\n'
        '            continue\n'
        '        matches.append((entry, meta))\n'
        '    return matches\n'
        '\n'
        '\n'
        'def find_manual_plugin_files(\n'
        '    target_uuid: Optional[str],\n'
        '    expected_credits: Optional[str] = "@w1bbex",\n'
        '    exclude_paths: Optional[list[str]] = None,\n'
        ') -> list[dict[str, str]]:\n'
        '    """List manual or legacy plugin files in plugins/ matching UUID and creator."""\n'
        '    return [\n'
        '        {\n'
        '            "filename": entry.name,\n'
        '            "path": entry.path,\n'
        '            "version": str(meta.get("version") or ""),\n'
        '            "name": str(meta.get("name") or ""),\n'
        '        }\n'
        '        for entry, meta in _iter_matching_legacy_files(target_uuid, expected_credits, exclude_paths)\n'
        '    ]\n'
        '\n'
        '\n'
        'def archive_legacy_plugins(\n'
        '    target_uuid: Optional[str],\n'
        '    expected_credits: Optional[str] = "@w1bbex",\n'
        '    exclude_paths: Optional[list[str]] = None,\n'
        ') -> list[str]:\n'
        '    """Move manual or legacy @w1bbex plugins matching target_uuid into plugins/w1bbex/archive/."""\n'
        '    matches = _iter_matching_legacy_files(target_uuid, expected_credits, exclude_paths)\n'
        '    if not matches:\n'
        '        return []\n'
        '\n'
        '    archive_dir = os.path.join(PATHS.plugins_dir, "w1bbex", "archive")\n'
        '    archived: list[str] = []\n'
        '    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")\n'
        '\n'
        '    for entry, _meta in matches:\n'
        '        os.makedirs(archive_dir, exist_ok=True)\n'
        '        stem, ext = os.path.splitext(entry.name)\n'
        '        dest = os.path.join(archive_dir, f"{stem}_{stamp}{ext}")\n'
        '        counter = 1\n'
        '        while os.path.exists(dest):\n'
        '            dest = os.path.join(archive_dir, f"{stem}_{stamp}_{counter}{ext}")\n'
        '            counter += 1\n'
        '        try:\n'
        '            shutil.move(entry.path, dest)\n'
        '            archived.append(entry.name)\n'
        '            logger.info("Archived legacy plugin %s -> %s", entry.path, dest)\n'
        '        except OSError:\n'
        '            logger.exception("Failed archiving legacy plugin %s", entry.path)\n'
        '    return archived\n'
        '\n'
        '\n'
        'def generate_loader(\n'
        '    plugin_name: str,\n'
        '    plugin_label: str,\n'
        '    folder_name: str,\n'
        '    api_name: str,\n'
        '    api_version: str,\n'
        '    api_desc: str,\n'
        ') -> str:\n'
        '    """Generate and atomically write the Cardinal loader stub for a plugin binary."""\n'
        '    safe_label = sanitize_segment(plugin_label, "plugin")\n'
        '    safe_folder = sanitize_segment(folder_name, "plugin_build")\n'
        '    loader_path = os.path.join(PATHS.plugins_dir, f"{safe_label}.py")\n'
        '    loader_code = (\n'
        '        f"{LOADER_HEADER}\\n"\n'
        '        "import os\\n"\n'
        '        "import importlib.util\\n"\n'
        '        "import uuid\\n\\n"\n'
        '        f"base_dir = os.path.join(os.path.dirname(__file__), \'w1bbex\', {repr(safe_folder)})\\n"\n'
        '        "pyd_path = None\\n"\n'
        '        "if os.path.exists(base_dir):\\n"\n'
        '        "    for fname in sorted(os.listdir(base_dir)):\\n"\n'
        '        "        if fname.endswith((\'.pyd\', \'.so\', \'.py\')):\\n"\n'
        '        "            pyd_path = os.path.join(base_dir, fname)\\n"\n'
        '        "            if fname.endswith((\'.pyd\', \'.so\')):\\n"\n'
        '        "                break\\n\\n"\n'
        '        "if not pyd_path:\\n"\n'
        '        "    raise ImportError(\'Бинарный файл плагина не найден!\')\\n\\n"\n'
        '        f"spec = importlib.util.spec_from_file_location({repr(safe_label)}, pyd_path)\\n"\n'
        '        "if spec is None or spec.loader is None:\\n"\n'
        '        "    raise ImportError(f\'Не удалось создать загрузчик для {pyd_path}\')\\n"\n'
        '        "module = importlib.util.module_from_spec(spec)\\n"\n'
        '        "spec.loader.exec_module(module)\\n\\n"\n'
        '        "for name in dir(module):\\n"\n'
        '        "    if not name.startswith(\'__\'):\\n"\n'
        '        "        globals()[name] = getattr(module, name)\\n\\n"\n'
        '        f"NAME = {repr(api_name)}\\n"\n'
        '        f"VERSION = {repr(api_version)}\\n"\n'
        '        f"DESCRIPTION = {repr(api_desc)}\\n"\n'
        '        f"CREDITS = getattr(module, \'CREDITS\', {repr(CREDITS)})\\n"\n'
        '        "UUID = getattr(module, \'UUID\', str(uuid.uuid4()))\\n"\n'
        '        "SETTINGS_PAGE = getattr(module, \'SETTINGS_PAGE\', False)\\n"\n'
        '    )\n'
        '    atomic_write_bytes(loader_path, loader_code.encode("utf-8"))\n'
        '    return loader_path\n'
        '\n'
        '\n'
        'def download_plugin(\n'
        '    cardinal: Any,\n'
        '    plugin_name: str,\n'
        '    license_key: Optional[str],\n'
        '    tg_user: Any,\n'
        ') -> tuple[bool, str]:\n'
        '    """Download, verify, install, and persist metadata for a plugin build (.py, .pyd, .so)."""\n'
        '    payload = {\n'
        '        "plugin_name": plugin_name,\n'
        '        "license_key": (license_key or "").strip(),\n'
        '        "system": get_sys_info(),\n'
        '        "funpay": get_funpay_identity(cardinal),\n'
        '        "telegram": get_telegram_identity(tg_user),\n'
        '    }\n'
        '    try:\n'
        '        resp = requests.post(f"{API_BASE}/download", json=payload, timeout=15, proxies=NO_PROXY)\n'
        '    except requests.RequestException as exc:\n'
        '        logger.error("Download plugin error: %s", exc)\n'
        '        return False, f"Ошибка сети: {exc}"\n'
        '\n'
        '    if resp.status_code != 200:\n'
        '        err_json = safe_json(resp)\n'
        '        return False, (\n'
        '            str(err_json["error"])\n'
        '            if (err_json and err_json.get("error"))\n'
        '            else f"Ошибка сервера: HTTP {resp.status_code}"\n'
        '        )\n'
        '\n'
        '    content_type = resp.headers.get("Content-Type", "").lower()\n'
        '    if "application/json" in content_type or resp.content.lstrip().startswith(b"{"):\n'
        '        json_err = safe_json(resp)\n'
        '        if json_err is not None and not json_err.get("success", True):\n'
        '            return False, str(json_err.get("error", "Неизвестная ошибка API."))\n'
        '    if not resp.content:\n'
        '        return False, "Сервер вернул пустой файл сборки."\n'
        '\n'
        '    raw_filename = resp.headers.get("X-Filename", f"{plugin_name}_Release.py")\n'
        '    base_filename = raw_filename.replace("\\\\", "/").rsplit("/", 1)[-1].strip()\n'
        '    if (\n'
        '        not base_filename\n'
        '        or not base_filename.endswith(SUPPORTED_PLUGIN_EXTENSIONS)\n'
        '        or base_filename in (".", "..")\n'
        '    ):\n'
        '        filename = f"{sanitize_segment(plugin_name, \'plugin\')}.py"\n'
        '    else:\n'
        '        ext = next(e for e in SUPPORTED_PLUGIN_EXTENSIONS if base_filename.endswith(e))\n'
        '        filename = f"{sanitize_segment(base_filename[:-len(ext)], plugin_name)}{ext}"\n'
        '\n'
        '    plugin_info = next((x for x in get_plugins() if x.get("id") == plugin_name), None)\n'
        '    plugin_label = plugin_label_from_info(plugin_name, plugin_info)\n'
        '    version = str(plugin_info.get("latest_version", "v1.0")) if plugin_info else "v1.0"\n'
        '    if filename.lower().endswith(".py"):\n'
        '        folder_name = sanitize_segment(plugin_label, sanitize_segment(plugin_name, "plugin"))\n'
        '    else:\n'
        '        folder_name = sanitize_segment(f"{plugin_name}_{version}", f"{plugin_name}_build")\n'
        '    plugin_dir = os.path.join(PATHS.plugins_dir, "w1bbex", folder_name)\n'
        '    save_path = os.path.join(plugin_dir, filename)\n'
        '    api_name = str(plugin_info.get("name", plugin_label)) if plugin_info else plugin_label\n'
        '    api_desc = (\n'
        '        str(plugin_info.get("description", "Загружено через W1bbex Hub"))\n'
        '        if plugin_info\n'
        '        else "Загружено через W1bbex Hub"\n'
        '    )\n'
        '    old_bin_dir = (load_data().get("installed") or {}).get(plugin_name, {}).get("bin_dir")\n'
        '\n'
        '    try:\n'
        '        atomic_write_bytes(save_path, resp.content)\n'
        '        save_abs = os.path.normcase(os.path.abspath(save_path))\n'
        '        if os.path.isdir(plugin_dir):\n'
        '            for entry_name in os.listdir(plugin_dir):\n'
        '                if entry_name.lower().endswith(SUPPORTED_PLUGIN_EXTENSIONS):\n'
        '                    candidate = os.path.join(plugin_dir, entry_name)\n'
        '                    if os.path.normcase(os.path.abspath(candidate)) != save_abs and os.path.isfile(candidate):\n'
        '                        try:\n'
        '                            os.remove(candidate)\n'
        '                        except OSError:\n'
        '                            logger.warning("Could not remove stale plugin file %s", candidate, exc_info=True)\n'
        '\n'
        '        extracted_meta = extract_py_plugin_metadata(save_path) if save_path.lower().endswith(".py") else {}\n'
        '        target_uuid = (plugin_info.get("uuid") if plugin_info else None) or extracted_meta.get("uuid")\n'
        '        target_credits = (\n'
        '            (plugin_info.get("credits") if plugin_info else None)\n'
        '            or extracted_meta.get("credits")\n'
        '            or "@w1bbex"\n'
        '        )\n'
        '        archived_files = archive_legacy_plugins(target_uuid=target_uuid, expected_credits=target_credits)\n'
        '\n'
        '        loader_path = generate_loader(plugin_name, plugin_label, folder_name, api_name, version, api_desc)\n'
        '        clean_old_plugin(plugin_name, new_stub_path=loader_path)\n'
        '        if old_bin_dir and os.path.normcase(os.path.abspath(old_bin_dir)) != os.path.normcase(\n'
        '            os.path.abspath(plugin_dir)\n'
        '        ):\n'
        '            queue_pending_deletion(old_bin_dir)\n'
        '        update_data(\n'
        '            lambda d: d.setdefault("installed", {}).__setitem__(\n'
        '                plugin_name,\n'
        '                {"name": plugin_label, "version": version, "stub_path": loader_path, "bin_dir": plugin_dir},\n'
        '            )\n'
        '        )\n'
        '    except PermissionError:\n'
        '        logger.exception("Plugin binary locked during reinstall of %s", plugin_name)\n'
        '        return (\n'
        '            False,\n'
        '            "Файл плагина занят процессом. Удалите плагин в Hub, выполните /restart и установите снова.",\n'
        '        )\n'
        '    except OSError as exc:\n'
        '        logger.exception("Failed saving plugin %s", plugin_name)\n'
        '        return False, f"Ошибка сохранения файлов на диск: {exc}"\n'
        '\n'
        '    archived_note = (\n'
        '        f" В архив (plugins/w1bbex/archive): {\', \'.join(archived_files)}."\n'
        '        if archived_files\n'
        '        else ""\n'
        '    )\n'
        '    return True, f"Плагин {plugin_label} (версия {version}) успешно скачан и установлен.{archived_note}"\n'
        '\n'
        '\n'
        'def validate_hub_source(raw_bytes: bytes, content_type: str = "") -> tuple[bool, str]:\n'
        '    """Verify downloaded W1bbexHub.py payload is valid Python with Cardinal metadata."""\n'
        '    try:\n'
        '        source_text = raw_bytes.decode("utf-8")\n'
        '    except UnicodeDecodeError:\n'
        '        return False, "Полученный файл поврежден (некорректная кодировка UTF-8)."\n'
        '\n'
        '    stripped = source_text.lstrip()\n'
        '    if "application/json" in content_type.lower() or stripped.startswith("{"):\n'
        '        err_msg = _extract_json_error(stripped)\n'
        '        if err_msg or "application/json" in content_type.lower():\n'
        '            return False, err_msg or "Сервер вернул JSON вместо файла плагина."\n'
        '\n'
        '    try:\n'
        '        tree = ast.parse(source_text)\n'
        '    except SyntaxError as exc:\n'
        '        return False, f"Получен поврежденный Python-файл: {exc.msg}"\n'
        '\n'
        '    assigned: set[str] = set()\n'
        '    for node in tree.body:\n'
        '        if isinstance(node, ast.Assign):\n'
        '            assigned.update(t.id for t in node.targets if isinstance(t, ast.Name))\n'
        '        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):\n'
        '            assigned.add(node.target.id)\n'
        '\n'
        '    if not {"VERSION", "UUID", "BIND_TO_PRE_INIT"}.issubset(assigned):\n'
        '        return False, "Скачанный файл не содержит обязательных метаданных W1bbex Hub."\n'
        '    return True, ""\n'
        '\n'
        '\n'
        'def download_and_update_hub(target_path: Optional[str] = None) -> tuple[bool, str]:\n'
        '    """Download latest W1bbexHub.py, validate syntax/metadata, and write atomically."""\n'
        '    try:\n'
        '        resp = requests.get(f"{API_BASE}/download_client", timeout=15, proxies=NO_PROXY)\n'
        '    except requests.RequestException as exc:\n'
        '        logger.error("Hub self-update network error: %s", exc)\n'
        '        return False, f"Ошибка сети: {exc}"\n'
        '\n'
        '    if resp.status_code != 200:\n'
        '        err_json = safe_json(resp)\n'
        '        err_msg = err_json.get("error") if err_json else f"HTTP {resp.status_code}"\n'
        '        return False, f"Ошибка скачивания: {err_msg}"\n'
        '\n'
        '    ok, reason = validate_hub_source(resp.content, resp.headers.get("Content-Type", ""))\n'
        '    if not ok:\n'
        '        return False, reason\n'
        '\n'
        '    dest = os.path.abspath(target_path or PATHS.hub_file)\n'
        '    try:\n'
        '        atomic_write_bytes(dest, resp.content)\n'
        '    except OSError as exc:\n'
        '        logger.exception("Failed writing Hub update")\n'
        '        return False, f"Ошибка записи файла обновления: {exc}"\n'
        '    return True, "W1bbex HUB успешно обновлен!"\n'
        '\n'
        '\n'
        'def collect_pending_updates(data: dict[str, Any], plugins: list[dict[str, Any]], now: float) -> list[dict[str, Any]]:\n'
        '    """Compute installed plugin updates that are eligible for notification."""\n'
        '    installed = data.get("installed") if isinstance(data.get("installed"), dict) else {}\n'
        '    notified = data.get("notified_updates") if isinstance(data.get("notified_updates"), dict) else {}\n'
        '    pending: list[dict[str, Any]] = []\n'
        '\n'
        '    for p in plugins:\n'
        '        pid = p.get("id", "")\n'
        '        if pid not in installed or not p.get("notify_users", True):\n'
        '            continue\n'
        '        curr_ver = str(installed[pid].get("version", "v1.0"))\n'
        '        latest = str(p.get("latest_version", "v1.0"))\n'
        '        if not is_newer_version(latest, curr_ver):\n'
        '            continue\n'
        '\n'
        '        update_key = f"{pid}_{latest}"\n'
        '        remind_at = notified.get(update_key)\n'
        '        if remind_at == -1 or (isinstance(remind_at, (int, float)) and now < remind_at):\n'
        '            continue\n'
        '\n'
        '        pending.append(\n'
        '            {\n'
        '                "id": pid,\n'
        '                "name": str(p.get("name", pid)),\n'
        '                "latest": latest,\n'
        '                "curr_ver": curr_ver,\n'
        '                "urgency": str(p.get("urgency", "medium")),\n'
        '                "changelog": str(p.get("changelog") or "Без описания"),\n'
        '                "update_key": update_key,\n'
        '            }\n'
        '        )\n'
        '    return pending\n'
        '\n'
        '\n'
        'def _versions_differ(ver_a: Optional[str], ver_b: Optional[str]) -> bool:\n'
        '    if not ver_a or not ver_b:\n'
        '        return False\n'
        '    return is_newer_version(ver_a, ver_b) or is_newer_version(ver_b, ver_a)\n'
        '\n'
        '\n'
        'def _normalize_plugin_path(raw_path: Optional[str]) -> str:\n'
        '    if not raw_path:\n'
        '        return ""\n'
        '    resolved = raw_path if os.path.isabs(raw_path) else os.path.join(PATHS.cardinal_root, raw_path)\n'
        '    return os.path.normcase(os.path.abspath(resolved))\n'
        '\n'
        '\n'
        'def get_disk_hub_pending_version() -> Optional[str]:\n'
        '    """Return newer Hub version written on disk awaiting Cardinal restart, if any."""\n'
        '    if not PATHS.hub_file or not os.path.isfile(PATHS.hub_file):\n'
        '        return None\n'
        '    meta = extract_py_plugin_metadata(PATHS.hub_file)\n'
        '    disk_ver = meta.get("version")\n'
        '    if disk_ver and is_newer_version(str(disk_ver), VERSION):\n'
        '        return str(disk_ver)\n'
        '    return None\n'
        '\n'
        '\n'
        'def find_loaded_plugin(\n'
        '    cardinal: Any,\n'
        '    plugin_info: Optional[dict[str, Any]],\n'
        '    installed_entry: Optional[dict[str, Any]],\n'
        ') -> tuple[Optional[str], Optional[Any]]:\n'
        '    """Locate a loaded PluginData instance in cardinal.plugins by UUID, stub path, or exact name."""\n'
        '    plugins_map = getattr(cardinal, "plugins", None)\n'
        '    if not isinstance(plugins_map, dict):\n'
        '        return None, None\n'
        '\n'
        '    hub_uuid = HUB_UUID.strip().lower()\n'
        '    target_uuid = str((plugin_info or {}).get("uuid") or "").strip().lower()\n'
        '    if target_uuid and target_uuid != hub_uuid:\n'
        '        for uid, pdata in plugins_map.items():\n'
        '            uid_str = str(uid).strip().lower()\n'
        '            pdata_uuid = str(getattr(pdata, "uuid", "") or "").strip().lower()\n'
        '            if uid_str == target_uuid or pdata_uuid == target_uuid:\n'
        '                return str(uid), pdata\n'
        '\n'
        '    stub_norm = _normalize_plugin_path((installed_entry or {}).get("stub_path"))\n'
        '    if stub_norm:\n'
        '        for uid, pdata in plugins_map.items():\n'
        '            if str(uid).strip().lower() == hub_uuid:\n'
        '                continue\n'
        '            if _normalize_plugin_path(getattr(pdata, "path", None)) == stub_norm:\n'
        '                return str(uid), pdata\n'
        '\n'
        '    target_name = str((plugin_info or {}).get("name") or "").strip().lower()\n'
        '    if target_name:\n'
        '        for uid, pdata in plugins_map.items():\n'
        '            if str(uid).strip().lower() == hub_uuid:\n'
        '                continue\n'
        '            if str(getattr(pdata, "name", "") or "").strip().lower() == target_name:\n'
        '                return str(uid), pdata\n'
        '\n'
        '    return None, None\n'
        '\n'
        '\n'
        'def inspect_plugin_state(\n'
        '    cardinal: Any,\n'
        '    plugin_info: dict[str, Any],\n'
        '    installed: Optional[dict[str, Any]] = None,\n'
        '    keys: Optional[dict[str, Any]] = None,\n'
        ') -> dict[str, Any]:\n'
        '    """Build a complete read-only status snapshot for one catalog plugin."""\n'
        '    pid = str(plugin_info.get("id", ""))\n'
        '    name = str(plugin_info.get("name", pid))\n'
        '    latest_version = str(plugin_info.get("latest_version", "v1.0"))\n'
        '    is_free = bool(plugin_info.get("is_free", False))\n'
        '\n'
        '    installed_map = installed if isinstance(installed, dict) else {}\n'
        '    keys_map = keys if isinstance(keys, dict) else {}\n'
        '    raw_entry = installed_map.get(pid)\n'
        '    installed_entry = raw_entry if isinstance(raw_entry, dict) else None\n'
        '    installed_version = str(installed_entry.get("version", "")) if installed_entry else None\n'
        '    stub_path = str(installed_entry.get("stub_path") or "") if installed_entry else ""\n'
        '    stub_exists = bool(stub_path and os.path.isfile(stub_path))\n'
        '    bin_dir = str(installed_entry.get("bin_dir") or "") if installed_entry else ""\n'
        '\n'
        '    plugins_registry_present = isinstance(getattr(cardinal, "plugins", None), dict)\n'
        '    loaded_uuid, loaded_plugin = find_loaded_plugin(cardinal, plugin_info, installed_entry)\n'
        '    loaded_version = (str(getattr(loaded_plugin, "version", "") or "") or None) if loaded_plugin else None\n'
        '    loaded_enabled = bool(getattr(loaded_plugin, "enabled", True)) if loaded_plugin else False\n'
        '    loaded_path = _normalize_plugin_path(getattr(loaded_plugin, "path", None)) if loaded_plugin else ""\n'
        '    loaded_file_exists = bool(loaded_path and os.path.isfile(loaded_path))\n'
        '    raw_cmds = getattr(loaded_plugin, "commands", None) if loaded_plugin else None\n'
        '    commands = [(str(cmd), str(desc)) for cmd, desc in raw_cmds.items()] if isinstance(raw_cmds, dict) else []\n'
        '    settings_page = bool(getattr(loaded_plugin, "settings_page", False)) if loaded_plugin else False\n'
        '\n'
        '    exclude = [stub_path] if stub_path else []\n'
        '    manual_files = find_manual_plugin_files(\n'
        '        plugin_info.get("uuid"),\n'
        '        plugin_info.get("credits") or "@w1bbex",\n'
        '        exclude_paths=exclude,\n'
        '    )\n'
        '    plugin_label = plugin_label_from_info(pid, plugin_info)\n'
        '    storage_dir = os.path.join(PATHS.cardinal_root, "storage", "w1bbex", sanitize_segment(plugin_label, pid))\n'
        '    storage_dir_exists = os.path.isdir(storage_dir)\n'
        '\n'
        '    key_val = str(keys_map.get(pid) or "")\n'
        '    has_key = bool(key_val)\n'
        '    masked_key = f"{key_val[:6]}…{key_val[-4:]}" if len(key_val) > 12 else key_val\n'
        '    has_update = bool(installed_entry is not None and is_newer_version(latest_version, installed_version or "0"))\n'
        '\n'
        '    needs_restart = False\n'
        '    restart_action = "general"\n'
        '    if installed_entry is not None:\n'
        '        if not stub_exists:\n'
        '            status_code = "broken_files"\n'
        '        elif not plugins_registry_present:\n'
        '            status_code = "installed"\n'
        '        elif loaded_plugin is None:\n'
        '            status_code = "restart_install"\n'
        '            needs_restart = True\n'
        '            restart_action = "install"\n'
        '        elif _versions_differ(installed_version, loaded_version):\n'
        '            status_code = "restart_update"\n'
        '            needs_restart = True\n'
        '            restart_action = "update"\n'
        '        elif loaded_path != _normalize_plugin_path(stub_path):\n'
        '            status_code = "restart_install"\n'
        '            needs_restart = True\n'
        '            restart_action = "install"\n'
        '        elif not loaded_enabled:\n'
        '            status_code = "disabled"\n'
        '        else:\n'
        '            status_code = "active"\n'
        '    else:\n'
        '        if loaded_plugin is not None:\n'
        '            if loaded_file_exists:\n'
        '                status_code = "manual"\n'
        '            else:\n'
        '                status_code = "restart_delete"\n'
        '                needs_restart = True\n'
        '                restart_action = "delete"\n'
        '        elif manual_files:\n'
        '            status_code = "manual"\n'
        '        else:\n'
        '            status_code = "not_installed"\n'
        '\n'
        '    return {\n'
        '        "id": pid,\n'
        '        "name": name,\n'
        '        "plugin_info": plugin_info,\n'
        '        "latest_version": latest_version,\n'
        '        "is_free": is_free,\n'
        '        "description": str(plugin_info.get("description") or ""),\n'
        '        "status_code": status_code,\n'
        '        "needs_restart": needs_restart,\n'
        '        "restart_action": restart_action,\n'
        '        "installed_entry": installed_entry,\n'
        '        "installed_version": installed_version,\n'
        '        "stub_path": stub_path,\n'
        '        "stub_exists": stub_exists,\n'
        '        "bin_dir": bin_dir,\n'
        '        "loaded_uuid": loaded_uuid,\n'
        '        "loaded_version": loaded_version,\n'
        '        "loaded_enabled": loaded_enabled,\n'
        '        "loaded_file_exists": loaded_file_exists,\n'
        '        "commands": commands,\n'
        '        "settings_page": settings_page,\n'
        '        "manual_files": manual_files,\n'
        '        "storage_dir_exists": storage_dir_exists,\n'
        '        "has_key": has_key,\n'
        '        "masked_key": masked_key,\n'
        '        "has_update": has_update,\n'
        '    }\n'
        '\n'
        '\n'
        'def delete_plugin_files(plugin_name: str) -> dict[str, Any]:\n'
        '    """Remove Hub loader stub, delete or defer plugin binaries, and preserve license/user storage."""\n'
        '    data = load_data()\n'
        '    installed = data.get("installed") if isinstance(data.get("installed"), dict) else {}\n'
        '    keys = data.get("keys") if isinstance(data.get("keys"), dict) else {}\n'
        '    if plugin_name not in installed:\n'
        '        return {"ok": False, "error": "Плагин не установлен или уже удален."}\n'
        '\n'
        '    info = installed[plugin_name]\n'
        '    stub_path = info.get("stub_path")\n'
        '    bin_dir = info.get("bin_dir")\n'
        '\n'
        '    stub_ok, denial_reason = remove_hub_stub(stub_path)\n'
        '    if not stub_ok and denial_reason:\n'
        '        return {"ok": False, "error": denial_reason}\n'
        '\n'
        '    locked = queue_pending_deletion(bin_dir)\n'
        '    update_data(lambda cur: (cur.get("installed") or {}).pop(plugin_name, None))\n'
        '\n'
        '    return {\n'
        '        "ok": True,\n'
        '        "plugin_id": plugin_name,\n'
        '        "plugin_name": str(info.get("name") or plugin_name),\n'
        '        "version": str(info.get("version") or ""),\n'
        '        "stub_path": str(stub_path or ""),\n'
        '        "stub_name": os.path.basename(str(stub_path)) if stub_path else "",\n'
        '        "bin_dir": str(bin_dir or ""),\n'
        '        "bin_dir_name": os.path.basename(str(bin_dir)) if bin_dir else "",\n'
        '        "bin_deferred": locked,\n'
        '        "kept_key": bool(keys.get(plugin_name)),\n'
        '    }\n'
        '\n'
        '\n'
        'def trigger_cardinal_restart(\n'
        '    delay_seconds: float = 0.35,\n'
        '    restart_fn: Optional[Callable[[], Any]] = None,\n'
        ') -> threading.Timer:\n'
        '    """Schedule Cardinal process restart slightly after HTTP/Telegram acknowledgement completes."""\n'
        '    if restart_fn is None:\n'
        '        try:\n'
        '            from Utils.cardinal_tools import restart_program as restart_fn  # type: ignore[import-not-found]\n'
        '        except Exception:\n'
        '            restart_fn = lambda: os.execl(sys.executable, sys.executable, *sys.argv)\n'
        '\n'
        '    def _run_restart() -> None:\n'
        '        try:\n'
        '            restart_fn()\n'
        '        except Exception:\n'
        '            logger.exception("Failed restarting Cardinal")\n'
        '\n'
        '    timer = threading.Timer(delay_seconds, _run_restart)\n'
        '    timer.daemon = True\n'
        '    timer.start()\n'
        '    return timer\n'
        '\n'
        '\n'
        'def invoke_plugin_command(\n'
        '    cardinal: Any,\n'
        '    loaded_plugin: Any,\n'
        '    base_message: Any,\n'
        '    from_user: Any,\n'
        ') -> tuple[bool, str]:\n'
        '    """Dispatch the plugin\'s primary slash command via Cardinal\'s registered bot message handlers."""\n'
        '    if not getattr(loaded_plugin, "enabled", True):\n'
        '        return False, "Плагин отключён в настройках Cardinal — сначала включите его."\n'
        '\n'
        '    raw_commands = getattr(loaded_plugin, "commands", None)\n'
