        '\n'
        'def run_update_check_cycle(cardinal: Any) -> int:\n'
        '    """Check installed plugins once and notify the owner about eligible updates."""\n'
        '    data = load_data()\n'
        '    installed = data.get("installed") if isinstance(data.get("installed"), dict) else {}\n'
        '    tg_id = data.get("owner_tg_id")\n'
        '    if not installed or not tg_id or not data.get("notify_updates", True):\n'
