        '        logger.exception("Failed sending post-restart Hub report to chat %s", chat_id)\n'
        '        return False\n'
        '\n'
        '\n'
        'class HubController:\n'
        '    """Handles Telegram commands, callback queries, and step flows for W1bbex Hub."""\n'
        '\n'
        '    def __init__(self, cardinal: Any) -> None:\n'
