        '\n'
        '    def activate_key_handler(self, c: CallbackQuery) -> None:\n'
        '        msg = self._send_html(\n'
        '            c.message.chat.id,\n'
        '            "🔑 <b>Активация ключа</b>\\n\\nВведите ваш лицензионный ключ в чат:\\n"\n'
