        '        return None\n'
        '\n'
        '    def show_licenses(self, c: CallbackQuery) -> None:\n'
        '        text, kb = render_licenses(load_data().get("keys") or {})\n'
        '        self._edit_html(text, c.message.chat.id, c.message.id, reply_markup=kb)\n'
        '\n'
        '    def install_plugin(self, c: CallbackQuery, plugin_name: Optional[str]) -> Any:\n'
