        'def init_cardinal(cardinal: Cardinal) -> HubController:\n'
        '    """Register Cardinal commands, callback routes, and message handlers."""\n'
        '    configure_file_logging()\n'
        '    controller = HubController(cardinal)\n'
        '    tg, bot = cardinal.telegram, cardinal.telegram.bot\n'
        '\n'
        '    try:\n'
        '        cardinal.add_telegram_commands(UUID, [("hub", "Управление W1bbex Hub", True)])\n'
        '    except Exception:\n'
        '        logger.exception("Не удалось зарегистрировать команды W1bbex Hub")\n'
        '\n'
        '    exact_routes = {\n'
        '        "hub:main": controller.main_menu,\n'
        '        "hub:plugins_menu": lambda c: controller.plugins_menu(c, force_refresh=False),\n'
        '        "hub:plugins_refresh": lambda c: controller.plugins_menu(c, force_refresh=True),\n'
        '        "hub:cancel_step": controller.cancel_step,\n'
        '        "hub:activate_key": controller.activate_key_handler,\n'
        '        "hub:licenses": controller.show_licenses,\n'
        '        "hub:resources": controller.resources_menu,\n'
        '        "hub:update_hub": controller.hub_update_handler,\n'
        '        "hub:toggle_notify": controller.toggle_notify,\n'
        '        "hub:toggle_notify_from_msg": controller.toggle_notify_msg_handler,\n'
        '    }\n'
        '    prefix_routes = (\n'
        '        ("hub:info:", controller.plugin_info_menu),\n'
        '        ("hub:install:", controller.install_plugin),\n'
        '        ("hub:trial:", controller.trial_request),\n'
        '        ("hub:trial_confirm:", controller.trial_confirm),\n'
        '        ("hub:delete:", controller.delete_plugin_handler),\n'
        '        ("hub:remind:", controller.remind_handler),\n'
        '        ("hub:restart:", controller.restart_cardinal_handler),\n'
        '        ("hub:open:", controller.open_plugin_handler),\n'
        '    )\n'
        '    try:\n'
        '        for cb_name, fn in exact_routes.items():\n'
        '            tg.cbq_handler(controller.wrap_cb(fn), func=lambda c, name=cb_name: c.data == name)\n'
        '        for prefix, fn in prefix_routes:\n'
        '            tg.cbq_handler(\n'
        '                controller.wrap_cb(lambda c, p=prefix, h=fn: h(c, _parse_cb_arg(c.data, p))),\n'
        '                func=lambda c, p=prefix: bool(c.data and c.data.startswith(p)),\n'
        '            )\n'
        '    except Exception:\n'
        '        logger.exception("Hub callback registration error")\n'
        '\n'
        '    register_msg = getattr(tg, "msg_handler", None)\n'
        '    if callable(register_msg):\n'
        '        register_msg(controller.hub_command, commands=["hub"])\n'
        '        register_msg(\n'
        '            controller.set_key_command,\n'
        '            func=lambda m: bool(getattr(m, "text", None) and m.text.startswith("!hub_key")),\n'
        '        )\n'
        '    else:\n'
        '        bot.message_handler(commands=["hub"])(controller.hub_command)\n'
        '        bot.message_handler(func=lambda m: bool(getattr(m, "text", None) and m.text.startswith("!hub_key")))(\n'
        '            controller.set_key_command\n'
        '        )\n'
        '    return controller\n'
        '\n'
        '\n'
        'def custom_init(cardinal: Cardinal) -> None:\n'
        '    """Cardinal BIND_TO_PRE_INIT entry point."""\n'
        '    configure_file_logging()\n'
        '    process_pending_deletions()\n'
        '    init_cardinal(cardinal)\n'
        '    STOP_EVENT.clear()\n'
        '    threading.Thread(\n'
        '        target=_update_checker_loop,\n'
        '        args=(cardinal, STOP_EVENT),\n'
        '        name="W1bbexHubUpdateChecker",\n'
        '        daemon=True,\n'
