        '    """Write bytes atomically via same-directory temp file, fsync, and os.replace."""\n'
        '    target_abs = os.path.abspath(target_path)\n'
        '    parent = os.path.dirname(target_abs)\n'
        '    os.makedirs(parent, exist_ok=True)\n'
