        '    try:\n'
        '        with os.fdopen(fd, "wb") as f:\n'
        '            f.write(content)\n'
        '            f.flush()\n'
        '            os.fsync(f.fileno())\n'
        '        os.replace(tmp_path, target_abs)\n'
        '    except Exception:\n'
        '        if os.path.exists(tmp_path):\n'
        '            try:\n'
        '                os.unlink(tmp_path)\n'
        '            except OSError:\n'
        '                logger.warning("Failed removing temp file %s", tmp_path, exc_info=True)\n'
        '        raise\n'
        '\n'
        '\n'
