        '            with open(pending_file, "r", encoding="utf-8") as f:\n'
        '                loaded = json.load(f)\n'
        '            pending = loaded if isinstance(loaded, list) else []\n'
        '        except (OSError, ValueError):\n'
        '            logger.exception("Failed reading pending deletions file: %s", pending_file)\n'
        '            return\n'
        '\n'
        '        still_pending: list[str] = []\n'
        '        for path in pending:\n'
        '            if isinstance(path, str) and path and os.path.exists(path):\n'
