        '\n'
        '\n'
        'def queue_pending_deletion(target_dir: Optional[str]) -> bool:\n'
        '    """Delete target_dir immediately or queue for next startup if locked. Returns True if deferred."""\n'
        '    if not target_dir or not os.path.exists(target_dir):\n'
        '        return False\n'
        '    try:\n'
        '        shutil.rmtree(target_dir)\n'
        '        return False\n'
        '    except OSError as exc:\n'
