        '                with open(pending_file, "r", encoding="utf-8") as f:\n'
        '                    loaded = json.load(f)\n'
        '                if isinstance(loaded, list):\n'
        '                    pending = [p for p in loaded if isinstance(p, str)]\n'
        '            except (OSError, ValueError):\n'
        '                logger.warning("Rebuilding corrupt pending_delete.json", exc_info=True)\n'
        '        if target_dir not in pending:\n'
        '            pending.append(target_dir)\n'
        '        atomic_write_json(pending_file, pending)\n'
        '    return True\n'
        '\n'
        '\n'
        'def load_data() -> dict[str, Any]:\n'
        '    """Load Hub config from disk, backing up corrupt JSON files instead of silently wiping them."""\n'
        '    data_file = PATHS.data_file\n'
        '    with DATA_LOCK:\n'
        '        if not os.path.exists(data_file):\n'
        '            default_data: dict[str, Any] = {"keys": {}}\n'
        '            try:\n'
        '                atomic_write_json(data_file, default_data)\n'
        '            except OSError:\n'
